internal val infectionsHLConditions: List<Condition> = listOf(
    Condition(
        id = "inf-hepatitis-c", title = "Hepatitis C",
        summary = "Blood-borne chronic viral hepatitis (HCV) progressing silently to cirrhosis and HCC; confirm viremia by HCV RNA PCR, check HBsAg/cirrhosis status, and cure (>95% SVR12) with 12–24 weeks of all-oral pangenotypic DAAs.",
        keywords = listOf("hepatitis c", "hcv", "anti-hcv", "hcv rna", "daa", "sofosbuvir", "daclatasvir", "velpatasvir", "svr12", "apri", "fibroscan", "cirrhosis", "nvhcp", "pangenotypic"),
        population = Population.Infections,
        firstSteps = listOf(
            "Confirm active viremia with HCV RNA RT-PCR before starting DAAs — never treat on an anti-HCV antibody result alone.",
            "Stage fibrosis/cirrhosis via FibroScan or APRI / FIB-4 and compute the Child-Turcotte-Pugh (CTP) score if cirrhotic (determines 12 vs 24 wk duration and specialist referral).",
            "Screen every patient for HBsAg, anti-HBc, and HIV before DAA initiation to prevent fatal HBV reactivation and check ART interactions.",
            "Review concurrent drugs (efavirenz, rifampicin, amiodarone, anticonvulsants, PPIs) and counsel on adherence and reinfection prevention.",
        ),
        info = listOf(
            InfoBlock("Investigation of choice (IOC)", listOf(
                "Screening test: Anti-HCV antibody by ELISA or RDT.",
                "Confirmatory IOC: HCV RNA RT-PCR (qualitative/quantitative); SVR12 (undetectable HCV RNA 12 weeks post-treatment) confirms virological cure.",
                "Cirrhosis staging: FibroScan (≥12.5 kPa = F4 cirrhosis) or APRI >2.0 / FIB-4 >3.25. Genotyping is not required for pangenotypic DAAs (note: Genotype 3 causes >70% of Indian HCV).",
            ), listOf(cite("inf-hl-nvhcp-lab-2018"), cite("inf-hl-who-hcv-2022"))),
            InfoBlock("Other Investigations & Key Findings", listOf(
                "Mandatory pre-DAA HBV panel (HBsAg, anti-HBc) and HIV serology; baseline CBC (platelets <150,000/µL suggests portal hypertension), LFTs, INR, creatinine/eGFR, pregnancy test, and abdominal USG.",
                "CTP Class A (5–6) = compensated; CTP Class B/C (≥7: ascites, encephalopathy, bilirubin >2–3, albumin ≤3.5, INR ≥1.7) = decompensated cirrhosis requiring hepatology care. Cirrhotic patients require lifelong 6-monthly USG + AFP HCC surveillance even after SVR12.",
            ), listOf(cite("inf-hl-fda-epclusa-2021"))),
        ),
        tiers = listOf(
            Tier("Drug of choice — Pangenotypic All-Oral DAAs (NVHCP India & WHO 2022)", null, listOf(
                Drug("Sofosbuvir + Daclatasvir (NVHCP India public-sector first-line)", "Sofosbuvir 400 mg + Daclatasvir 60 mg PO once daily × 12 weeks (non-cirrhotic) OR × 24 weeks (compensated cirrhosis or treatment-experienced)", cautions = listOf("Extend to 24 weeks in cirrhosis because Genotype 3 (dominant in India) achieves higher SVR12 with 24 weeks. Paediatrics (≥3 yr): ≥25 kg → 400/60 mg OD; 14–25 kg → 200/30 mg OD × 12 wk."), citations = listOf(cite("inf-hl-who-hcv-2022"), cite("inf-hl-nvhcp-punjab-2023"))),
                Drug("Sofosbuvir / Velpatasvir FDC (Single-tablet pangenotypic first-line)", "Sofosbuvir 400 mg / Velpatasvir 100 mg (1 tablet) PO once daily × 12 weeks (non-cirrhotic & compensated cirrhosis CTP A)", cautions = listOf("Avoid efavirenz, rifampicin, strong CYP/P-gp inducers, and co-administered PPIs."), citations = listOf(cite("inf-hl-who-hcv-2022"), cite("inf-hl-fda-epclusa-2021"))),
            )),
            Tier("Decompensated Cirrhosis, Retreatment, & Special Groups", null, listOf(
                Drug("Decompensated Cirrhosis (Child-Pugh B/C)", "Sofosbuvir 400 mg / Velpatasvir 100 mg PO OD + weight-based Ribavirin (start 600 mg/day, titrate up to 1,000 mg/day [<75 kg] or 1,200 mg/day [≥75 kg] in 2 divided doses) × 12 weeks — OR SOF/VEL × 24 weeks without ribavirin if RBV-ineligible", cautions = listOf("Manage at hepatology/transplant centre; monitor Hb for haemolysis; never use protease inhibitors."), citations = listOf(cite("inf-hl-fda-epclusa-2021"))),
                Drug("DAA Failure Retreatment & Special Groups", "Retreatment: SOF/VEL/Voxilaprevir 400/100/100 mg OD × 12 wk (CTP A only) OR NVHCP ATC fallback SOF/VEL + Ribavirin × 24 wk. Pregnancy: defer DAA until postpartum/after breastfeeding. HBsAg+: add/continue tenofovir through 12 wk post-DAA.", citations = listOf(cite("inf-hl-who-hcv-2022"), cite("inf-hl-fda-epclusa-2021"), cite("inf-hl-hcv-retx-india"))),
            )),
        ),
        avoid = listOf(
            Caution("Protease inhibitors (glecaprevir/pibrentasvir, voxilaprevir) in Child-Pugh B/C decompensated cirrhosis", "Risk of fatal hepatic decompensation.", listOf(cite("inf-hl-fda-epclusa-2021"))),
        ),
